import { NextResponse } from "next/server";

/**
 * Mini app manifest (Farcaster Mini Apps spec, also read by clients that open Farcaster mini apps).
 * accountAssociation proves domain ownership; it is generated by signing the domain with a Farcaster account
 * (Warpcast → Developers → Mini App Manifest Tool) and set through the public env vars below.
 */
export const dynamic = "force-static";

const SITE = (process.env.NEXT_PUBLIC_SITE_URL || "https://maxxagent-wine.vercel.app").replace(/\/$/, "");

export function GET() {
  const header = process.env.FARCASTER_ACCOUNT_HEADER;
  const payload = process.env.FARCASTER_ACCOUNT_PAYLOAD;
  const signature = process.env.FARCASTER_ACCOUNT_SIGNATURE;
  const body = {
    ...(header && payload && signature ? { accountAssociation: { header, payload, signature } } : {}),
    miniapp: {
      version: "1",
      name: "MAXXAGENT",
      homeUrl: `${SITE}/`,
      iconUrl: `${SITE}/brand/miniapp-icon-1024.png`,
      splashImageUrl: `${SITE}/brand/miniapp-splash-200.png`,
      splashBackgroundColor: "#03060e",
      subtitle: "Tokenized stock indexes",
      description:
        "Build your own index of tokenized stocks on Base or let an agent propose one, then buy it in one click from your own wallet. Not financial advice",
      primaryCategory: "finance",
      tags: ["stocks", "index", "base", "agent", "portfolio"],
      heroImageUrl: `${SITE}/brand/maxxagent-og.png`,
      tagline: "Your own stock index on Base",
      ogTitle: "MAXXAGENT",
      ogDescription: "Build and buy your own index of tokenized stocks on Base, from your own wallet.",
      ogImageUrl: `${SITE}/brand/maxxagent-og.png`,
      requiredChains: ["eip155:8453"],
      requiredCapabilities: ["wallet.getEthereumProvider"],
    },
  };
  return NextResponse.json(body, { headers: { "Cache-Control": "public, max-age=300" } });
}
